parameters.jsCode:
const s = $('Propose settings').first().json;
const products = $('Get products').all().flatMap(i => i.json.data.products.nodes);
const live = products.filter(p => !p.tracksInventory || p.totalInventory > 0);
const OK_TYPES = ['single_line_text_field', 'number_integer', 'number_decimal', 'boolean'];
const defs = Object.fromEntries($('Get definitions').first().json.data.metafieldDefinitions.nodes
  .filter(d => d.namespace === s.namespace && d.capabilities.smartCollectionCondition.enabled && OK_TYPES.includes(d.type.name))
  .map(d => [d.key, d]));
const collections = $('Get collections').all().flatMap(i => i.json.data.collections.nodes);
const sig = rules => rules.map(r => [r.column, r.key ?? '', String(r.condition).toLowerCase()].join('|')).sort().join('&');

// Anything Shopify already has, by rule or by handle, is taken.
const taken = new Set(collections.map(c => 'handle:' + c.handle));
for (const c of collections) if (c.ruleSet && !c.ruleSet.appliedDisjunctively)
  taken.add(sig(c.ruleSet.rules.map(r => ({ ...r, key: r.conditionObject?.metafieldDefinition?.key }))));
for (const row of $('Get proposals').all()) if (row.json.key) taken.add(row.json.key);

const byType = {};
for (const p of live) if (p.productType) (byType[p.productType] ??= []).push(p);
const typesPerVendor = {};
for (const p of live) if (p.vendor) (typesPerVendor[p.vendor] ??= new Set()).add(p.productType);

const out = [];
const add = (c) => {
  c.key = sig(c.rules);
  if (taken.has(c.key) || c.products.length < s.min_products || c.products.length === byType[c.product_type].length) return;
  out.push(c);
};
for (const [type, items] of Object.entries(byType)) {
  const groups = {};
  for (const p of items) for (const m of p.metafields.nodes) {
    const d = defs[m.key];
    if (!d || (d.type.name === 'boolean' && m.value !== 'true')) continue;
    (groups[m.key + '=' + m.value] ??= { d, value: m.value, products: [] }).products.push(p);
  }
  for (const g of Object.values(groups)) add({ source: 'attribute', product_type: type, attr_key: g.d.key,
    attr_label: g.d.name, attr_value: g.value, products: g.products,
    rules: [{ column: 'TYPE', relation: 'EQUALS', condition: type },
            { column: 'PRODUCT_METAFIELD_DEFINITION', relation: 'EQUALS', condition: g.value, conditionObjectId: g.d.id, key: g.d.key }] });
  for (const [vendor, types] of Object.entries(typesPerVendor)) if (types.size >= 2) add({ source: 'brand_type',
    product_type: type, vendor, products: items.filter(p => p.vendor === vendor),
    rules: [{ column: 'TYPE', relation: 'EQUALS', condition: type }, { column: 'VENDOR', relation: 'EQUALS', condition: vendor }] });
}
return out.sort((a, b) => b.products.length - a.products.length).slice(0, s.max_candidates).map(c => ({ json: {
  ...c, live_count: c.products.length, vendors: [...new Set(c.products.map(p => p.vendor))],
  sample_titles: c.products.slice(0, 5).map(p => p.title),
  sibling_titles: collections.filter(k => k.ruleSet?.rules.some(r => r.column === 'TYPE' && r.condition === c.product_type)).map(k => k.title),
  products: undefined } }));

const all = $('Find candidates').all().map(i => i.json);
const vendors = [...new Set($('Get products').all().flatMap(i => i.json.data.products.nodes.map(p => p.vendor)).filter(Boolean))];
const words = t => String(t).toLowerCase().split(/[^a-z0-9.+]+/).filter(Boolean);
const slug = t => t.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const seen = new Set();
// Models wrap JSON in code fences and leave trailing commas, so read it leniently.
const readJson = t => {
  try { return JSON.parse(String(t || '').replace(/```(json)?/gi, '').replace(/,\s*([}\]])/g, '$1').trim()); }
  catch (e) { return {}; }
};

return $input.all().map((item, i) => {
  const c = all[i];
  const ai = readJson(item.json.text);
  const own = c.source === 'brand_type' ? c.vendor.toLowerCase() : null;
  const raw = c.source === 'brand_type' ? `${c.vendor} ${c.product_type}` : `${c.attr_value} ${c.product_type}`;
  // Any word with a digit (a size, a spec, a model code) must come from the value or the category.
  const allowed = new Set(words(raw));
  const problems = (text) => {
    const low = ` ${String(text).toLowerCase()} `;
    const found = vendors.filter(v => v.toLowerCase() !== own && low.includes(` ${v.toLowerCase()} `)).map(v => 'brand ' + v);
    return found.concat(words(text).filter(w => /\d/.test(w) && !allowed.has(w)).map(w => 'not in the data: ' + w));
  };
  const aiOk = ai.title && ai.title.length <= 60 && problems(ai.title).length === 0;
  const title = aiOk ? ai.title.trim() : raw;
  let keywords = (ai.keywords ?? []).map(k => k.toLowerCase().replace(/[^a-z0-9 .+&'-]/g, ' ').replace(/\s+/g, ' ').trim())
    .filter(k => k && k.length <= 80 && k.split(' ').length <= 10 && problems(k).length === 0);
  if (!keywords.length) keywords = [raw.toLowerCase()];
  const handle = slug(title);
  const dupe = seen.has(handle); seen.add(handle);
  return { json: { ...c, raw_title: raw, title, handle, keywords: [...new Set(keywords)],
    name_source: aiOk ? 'ai' : 'fallback', name_problems: aiOk ? [] : problems(ai.title ?? ''),
    skip_reason: ai.skip_reason || (dupe ? 'same title as another proposal this week' : '') } };
});

