const s = $('Propose settings').first().json;
const task = $input.first().json.tasks?.[0];
if (!task || task.status_code !== 20000) throw new Error('Search volume failed: ' + (task?.status_message || 'no task'));
const vol = Object.fromEntries((task.result ?? []).map(r => [r.keyword.toLowerCase(), r.search_volume ?? 0]));
return $('Check names').all().map(({ json: c }) => {
  // Google Ads reports close variants with one shared volume, so take the best keyword, never a sum.
  const best = c.keywords.map(k => ({ k, v: vol[k] ?? 0 })).sort((a, b) => b.v - a.v)[0];
  const status = c.skip_reason ? 'ai_skipped' : best.v < s.min_volume ? 'no_demand' : 'pending';
  return { json: { ...c, main_keyword: best.k, volume: best.v, status } };
});

const s = $('Propose settings').first().json;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const demand = vol => vol ? clamp(Math.log10(vol + 1) / Math.log10(5000) * 40, 0, 40) : 0; // 5,000 searches = full 40
const depth = n => clamp(n / 50 * 25, 0, 25);                                          // 50 products = full 25
const gap = ranksNow => ranksNow ? 8 : 20;                                             // more to win if you don't rank
const ease = kd => kd == null ? 8 : clamp((100 - kd) / 100 * 15, 0, 15);

const kd = {}, ranks = {};
const bare = d => String(d || '').toLowerCase().replace(/^www\./, '');
if ($('Keyword difficulty').isExecuted)
  for (const r of $('Keyword difficulty').first().json.tasks?.[0]?.result?.[0]?.items ?? []) kd[r.keyword] = r.keyword_difficulty;
if ($('Rank check').isExecuted)
  for (const it of $('Rank check').all()) {
    const t = it.json.tasks?.[0];
    ranks[t?.data?.keyword] = (t?.result?.[0]?.items ?? []).some(x => x.type === 'organic' && bare(x.domain).endsWith(bare(s.own_domain)));
  }
return $('Pick keyword').all().map(({ json: c }) => ({ json: { ...c, kd: kd[c.main_keyword] ?? null, ranks_now: !!ranks[c.main_keyword],
  score: c.status === 'pending' ? Math.round(demand(c.volume) + depth(c.live_count) + gap(ranks[c.main_keyword]) + ease(kd[c.main_keyword])) : 0 } }));

const s = $('Propose settings').first().json;
return $input.all().filter(i => i.json.status === 'pending' && i.json.score >= s.create_score)
  .sort((a, b) => b.json.score - a.json.score).slice(0, s.max_cards);

