const s = $('Brands settings').first().json;
const count = {};
for (const p of $('Get vendors').all().flatMap(i => i.json.data.products.nodes)) if (p.vendor) count[p.vendor] = (count[p.vendor] || 0) + 1;
const cols = $('Get brand collections').all().flatMap(i => i.json.data.collections.nodes);
// A brand page is a collection whose only rule is VENDOR EQUALS.
const hasPage = new Set(cols.filter(c => c.ruleSet?.rules.length === 1 && c.ruleSet.rules[0].column === 'VENDOR' && c.ruleSet.rules[0].relation === 'EQUALS')
  .map(c => c.ruleSet.rules[0].condition.toLowerCase()));
const handles = new Set(cols.map(c => c.handle));
const seen = new Set($('Get brand proposals').all().map(i => String(i.json.vendor || '').toLowerCase()));
const skip = new Set(s.exclude_vendors.map(v => v.toLowerCase()));
const slug = t => t.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
return Object.entries(count)
  .filter(([v]) => !skip.has(v.toLowerCase()) && !hasPage.has(v.toLowerCase()) && !seen.has(v.toLowerCase()) && !handles.has(slug(v)))
  .map(([v, n]) => ({ json: { key: 'VENDOR||' + v.toLowerCase(), source: 'brand', vendor: v, title: v, handle: slug(v), live_count: n,
    rule_set: JSON.stringify([{ column: 'VENDOR', relation: 'EQUALS', condition: v }]), status: s.review_brands ? 'pending' : 'approved' } }));

