const s = $('Retire settings').first().json;
const rows = $('Get all proposals').all().map(i => i.json);
const byCol = {};
for (const r of rows) if (r.collection_id) (byCol[r.collection_id] ??= []).push(r);
const cutoff = Date.now() - s.keep_days * 864e5;
const out = [];
for (const [id, rs] of Object.entries(byCol)) {
  const made = rs.find(r => r.kind === 'create' && r.status === 'applied' && r.source !== 'brand');
  if (!made) continue;
  const changes = rs.filter(r => r.kind !== 'create').sort((a, b) => a.id - b.id);
  if (changes.some(r => ['pending', 'approved', 'applying'].includes(r.status))) continue;    // a card is already out
  if (changes.some(r => r.status === 'skipped' && new Date(r.updatedAt) > cutoff)) continue;  // you chose to keep it recently
  const last = changes.filter(r => r.status === 'applied').at(-1);
  out.push({ json: { collection_id: id, title: made.title, handle: made.handle, source: made.source, live: !last || last.kind === 'restore' } });
}
return out;

const s = $('Retire settings').first().json;
const cols = $('Collections to check').all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
return $input.all().flatMap((it, i) => {
  const c = cols[i], col = it.json.data?.collection;
  if (!col) return [];                                         // deleted in Shopify
  const live = col.products.nodes.filter(p => p.status === 'ACTIVE' && (!p.tracksInventory || p.totalInventory > 0)).length;
  const kind = c.live && live < s.retire_below ? 'retire' : !c.live && live >= s.restore_at ? 'restore' : null;
  if (!kind) return [];
  return [{ json: { key: `${kind}|${c.collection_id}|${today}`, kind, source: c.source, title: c.title, handle: c.handle,
    collection_id: c.collection_id, live_count: live, floor: kind === 'retire' ? s.retire_below : s.restore_at } }];
});

